@js:
try {
    var result = [];
    csh();

    var push = (title, url, size) => result.push({
        "title": title,
        "url": url,
        "style": {
            "layout_flexGrow": 1,
            "layout_flexBasisPercent": size
        }
    });

    // 主切换筛选器: 人气热门/更新时间/新品上架/排行榜
    result.push(createFilter(
        "分类",
        ["人气热门", "更新时间", "新品上架", "排行榜"],
        "人气热门",
        "mainType",
        1
    ));

    var mainType = Get("mainType");
    infoMap.save();

    // 排序方式映射到URL片段
    var order_dic = {
        "人气热门": "",
        "更新时间": "order2",
        "新品上架": "order18"
    };

    // 题材映射
    var tag_dic = {
        "全部": "",
        "热血": "tag1",
        "恋爱": "tag2",
        "百合": "tag4",
        "彩虹": "tag5",
        "冒险": "tag6",
        "后宫": "tag9",
        "治愈": "tag10",
        "悬疑": "tag16",
        "搞笑": "tag18",
        "奇幻": "tag19",
        "历史": "tag24",
        "古风": "tag31",
        "都市": "tag33"
    };

    // 排行榜映射
    var rank_dic = {
        "人气榜": "",
        "完结榜": "?t=1",
        "少年榜": "?t=2",
        "少女榜": "?t=3",
        "热血榜": "?t=4",
        "恋爱榜": "?t=5",
        "日韩榜": "?t=6"
    };

    push("🔥" + mainType + "🔥", null, 1);

    if (mainType === "排行榜") {
        // 排行车子分类
        Object.keys(rank_dic).forEach(title => {
            var url = "/rank/" + rank_dic[title];
            push(title, url, 0.25);
        });
    } else {
        // 题材子分类 (根据排序方式组合URL)
        var order = order_dic[mainType];
        Object.keys(tag_dic).forEach(title => {
            var tag = tag_dic[title];
            var parts = ["comics"];
            if (tag) parts.push(tag);
            if (order) parts.push(order);
            var url = "/" + parts.join("-") + "-p{{page}}/";
            push(title, url, 0.25);
        });
    }

    JSON.stringify(result);
} catch (e) {
    java.log(e.message);
}

